import{_ as t,o,c as d,a1 as a}from"./chunks/framework.DceXOx8u.js";const m=JSON.parse('{"title":"Upgrade to stable: dependencies","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://andresayac.github.io/botmesh/guide/migration"}],["meta",{"property":"og:url","content":"https://andresayac.github.io/botmesh/guide/migration"}]]},"headers":[],"relativePath":"guide/migration.md","filePath":"guide/migration.md"}'),s={name:"guide/migration.md"};function i(n,e,r,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="upgrade-to-stable-dependencies" tabindex="-1">Upgrade to stable: dependencies <a class="header-anchor" href="#upgrade-to-stable-dependencies" aria-label="Permalink to &quot;Upgrade to stable: dependencies&quot;">​</a></h1><p>Step 2 of the <a href="./stable-migration#upgrade-checklist">upgrade checklist</a>. The stable line updates the dependencies of the public packages and finishes the <code>botwa</code> → <code>botmesh</code> rename. Each section says who is affected and what to do.</p><table tabindex="0"><thead><tr><th>Change</th><th>Who is affected</th><th>What to do</th></tr></thead><tbody><tr><td><a href="#prometheus-metric-names-botmesh-prefix"><code>botmesh_</code> metric names</a></td><td>Dashboards and alerts on <code>botwa_*</code></td><td>Rename the queries, or pass <code>{ prefix: &#39;botwa_&#39; }</code></td></tr><tr><td><a href="#environment-variables">Environment variables</a></td><td>Scripts that set <code>BOTWA_*</code></td><td>Rename (the old names are still read)</td></tr><tr><td><a href="#botmesh-redis-store-redis-is-a-peer-dependency"><code>redis</code> is a peer dependency</a></td><td><code>@botmesh/redis-store</code> users</td><td>Nothing, unless you typed clients with <code>NativeRedisClient</code></td></tr><tr><td><a href="#botmesh-baileys-ffmpeg-is-no-longer-bundled">ffmpeg is no longer bundled</a></td><td>Baileys bots that send voice notes</td><td>Install ffmpeg, or <code>ffmpeg-static</code></td></tr><tr><td><a href="#meta-providers-graph-api-v26-0">Graph API v26.0</a></td><td>Cloud API, Messenger, Instagram</td><td>Nothing, or pin <code>apiVersion</code></td></tr><tr><td><a href="#botmesh-ai-sdks-and-default-models">AI SDKs and default models</a></td><td>Gemini bots; bots without an explicit <code>model</code></td><td><code>pnpm add @google/genai</code>; set <code>model</code></td></tr><tr><td><a href="#names-that-stay">Names that stay</a></td><td>Everyone</td><td>Nothing: stored <code>botwa</code> keys and prefixes keep working</td></tr></tbody></table><h2 id="prometheus-metric-names-botmesh-prefix" tabindex="-1">Prometheus metric names: <code>botmesh_</code> prefix <a class="header-anchor" href="#prometheus-metric-names-botmesh-prefix" aria-label="Permalink to &quot;Prometheus metric names: `botmesh_` prefix&quot;">​</a></h2><p><code>toPrometheus(bot.metrics())</code> (<code>@botmesh/core</code>) now names every family <code>botmesh_*</code> instead of <code>botwa_*</code>, for example <code>botmesh_messages_in_total</code>. Dashboards and alerts that query the old names keep working if you pass the old prefix:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toPrometheus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(bot.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">metrics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), { prefix: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;botwa_&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p>The OpenTelemetry bridge (<code>@botmesh/otel</code>) moved from <code>botwa.*</code> to <code>botmesh.*</code> the same way (<code>otelMetricsPlugin({ prefix: &#39;botwa&#39; })</code> keeps the old names), and the control plane (<code>@botmesh/manager</code>) now serves <code>botmesh_manager_bots_registered</code> and <code>botmesh_manager_bots_running</code>.</p><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>New name</th><th>Old name (still read)</th><th>Where</th></tr></thead><tbody><tr><td><code>BOTMESH_DEV=1</code></td><td><code>BOT_WA_DEV=1</code> (still set)</td><td>set by <code>botmesh dev</code> for your bot code</td></tr><tr><td><code>BOTMESH_MANAGER_LOG_LEVEL</code></td><td><code>BOTWA_MANAGER_LOG_LEVEL</code></td><td>default logger of <code>BotManager</code></td></tr><tr><td><code>BOTMESH_DOCS_DIR</code></td><td><code>BOTWA_DOCS_DIR</code></td><td>docs tree of the MCP server</td></tr></tbody></table><p>The hot-reload query of <code>botmesh dev</code> is now <code>?botmesh_v=&lt;n&gt;</code> (it shows in stack traces only).</p><h2 id="botmesh-redis-store-redis-is-a-peer-dependency" tabindex="-1"><code>@botmesh/redis-store</code>: <code>redis</code> is a peer dependency <a class="header-anchor" href="#botmesh-redis-store-redis-is-a-peer-dependency" aria-label="Permalink to &quot;`@botmesh/redis-store`: `redis` is a peer dependency&quot;">​</a></h2><p><code>redis</code> (node-redis) moved from <code>dependencies</code> to <code>peerDependencies</code> with the range <code>^4.7.0 || ^5.0.0 || ^6.0.0</code>. npm and pnpm install a missing peer dependency on their own (node-redis 6), so <code>pnpm add @botmesh/redis-store</code> still works; if you already depend on <code>redis</code>, the store uses your version.</p><ul><li>node-redis 5 and 6 are now supported, on a single node and on Redis Cluster, with RESP2 or RESP3 (the node-redis 6 default).</li><li><code>NativeRedisClient</code> and <code>NativeRedisClusterClient</code> are now small structural interfaces instead of <code>ReturnType&lt;typeof createClient&gt;</code>, so the client of any supported major type-checks. Code that used them to call commands should use the type from <code>redis</code> instead (<code>ReturnType&lt;typeof createClient&gt;</code>).</li></ul><h2 id="botmesh-baileys-ffmpeg-is-no-longer-bundled" tabindex="-1"><code>@botmesh/baileys</code>: ffmpeg is no longer bundled <a class="header-anchor" href="#botmesh-baileys-ffmpeg-is-no-longer-bundled" aria-label="Permalink to &quot;`@botmesh/baileys`: ffmpeg is no longer bundled&quot;">​</a></h2><p>The provider no longer depends on <code>fluent-ffmpeg</code> (deprecated upstream) or <code>@ffmpeg-installer/ffmpeg</code> (unmaintained, an old ffmpeg). Voice notes are transcoded by running an ffmpeg binary directly, found in this order:</p><ol><li><code>FFMPEG_PATH</code>, when it is set;</li><li>the optional peer dependency <code>ffmpeg-static</code>, when it is installed and its binary was downloaded (with pnpm, allow its build script);</li><li><code>ffmpeg</code> on the <code>PATH</code> (<code>apt install ffmpeg</code>, <code>brew install ffmpeg</code>, <code>choco install ffmpeg</code>).</li></ol><p>Without any of them, a voice note rejects with an <code>UnsupportedContentError</code> that explains how to install ffmpeg (when <code>ffmpeg-static</code> is installed but its binary was never downloaded, the message says to allow its build script and reinstall it). Text, images and the rest are not affected. The Docker image of a bot that sends voice notes needs ffmpeg installed (or <code>ffmpeg-static</code>).</p><p>Baileys itself stays on <code>7.0.0-rc14</code>: no stable 7.x exists yet (see the <a href="https://github.com/andresayac/botmesh/tree/main/packages/baileys-provider#requirements" target="_blank" rel="noreferrer">package README</a> and its upstream upgrade policy).</p><h2 id="meta-providers-graph-api-v26-0" tabindex="-1">Meta providers: Graph API v26.0 <a class="header-anchor" href="#meta-providers-graph-api-v26-0" aria-label="Permalink to &quot;Meta providers: Graph API v26.0&quot;">​</a></h2><p><code>@botmesh/meta</code>, <code>@botmesh/messenger</code> and <code>@botmesh/instagram</code> now call Graph API <code>v26.0</code> by default (it was <code>v21.0</code>, which Meta retires on 2027-01-21). The send and webhook payloads the providers use did not change between those versions. To stay on a version, pin it:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CloudAPIProvider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* ... */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> apiVersion: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;v21.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p>WhatsApp&#39;s <code>played</code> status (a voice note was listened to) is now delivered as <code>status: &#39;read&#39;</code> with <code>platformData.played: true</code>; it used to be dropped.</p><h2 id="botmesh-ai-sdks-and-default-models" tabindex="-1"><code>@botmesh/ai</code>: SDKs and default models <a class="header-anchor" href="#botmesh-ai-sdks-and-default-models" aria-label="Permalink to &quot;`@botmesh/ai`: SDKs and default models&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Change</th><th>Before</th><th>Now</th></tr></thead><tbody><tr><td>Gemini SDK</td><td><code>@google/generative-ai</code> (deprecated upstream)</td><td><code>@google/genai</code> <code>^2</code>; the old SDK is still used, with a <code>DeprecationWarning</code>, when the new one is not installed</td></tr><tr><td>Anthropic default model</td><td><code>claude-opus-4-8</code></td><td><code>claude-opus-5-5</code></td></tr><tr><td>Gemini default model</td><td><code>gemini-2.0-flash</code> (shut down by Google)</td><td><code>gemini-3.8-flash</code></td></tr><tr><td><code>grok</code> preset model</td><td><code>grok-2-latest</code></td><td><code>grok-4.7</code></td></tr><tr><td><code>glm</code> preset model</td><td><code>glm-4-plus</code></td><td><code>glm-5.3</code></td></tr></tbody></table><p>To move a Gemini bot: <code>pnpm remove @google/generative-ai &amp;&amp; pnpm add @google/genai</code>. Nothing else changes in <code>aiPlugin</code>; <code>baseUrl</code> becomes the SDK&#39;s <code>httpOptions.baseUrl</code>. For Vertex AI, build the client yourself with <code>fromGoogleGenAI</code> (see <a href="/botmesh/guide/ai#gemini">Gemini</a>).</p><p>Default models are not covered by semver: set <code>model</code> when the choice matters. Claude Opus 5.5 always thinks (<code>thinking: &#39;off&#39;</code> lowers nothing on it; use <code>effort: &#39;low&#39;</code>) and its effort defaults to <code>medium</code>.</p><h2 id="botmesh-hub-botmesh-manifest-field" tabindex="-1"><code>@botmesh/hub</code>: <code>botmesh</code> manifest field <a class="header-anchor" href="#botmesh-hub-botmesh-manifest-field" aria-label="Permalink to &quot;`@botmesh/hub`: `botmesh` manifest field&quot;">​</a></h2><p>A plugin manifest declares its runtime range in <code>botmesh</code> (<code>&quot;botmesh&quot;: &quot;^2.0.0&quot;</code>). Manifests with the old <code>botwa</code> field are still accepted, and validation returns them with <code>botmesh</code>.</p><h2 id="eslint-plugin-botmesh-type-names" tabindex="-1"><code>eslint-plugin-botmesh</code>: type names <a class="header-anchor" href="#eslint-plugin-botmesh-type-names" aria-label="Permalink to &quot;`eslint-plugin-botmesh`: type names&quot;">​</a></h2><p>The exported types are <code>BotMeshConfigs</code> and <code>BotMeshPlugin</code>. The old <code>BotWaConfigs</code> and <code>BotWaPlugin</code> are kept as deprecated aliases of the same types, so existing imports keep compiling; rename them when convenient.</p><h2 id="names-that-stay" tabindex="-1">Names that stay <a class="header-anchor" href="#names-that-stay" aria-label="Permalink to &quot;Names that stay&quot;">​</a></h2><p>Some identifiers from the project&#39;s former name live in stored data. Renaming them would hide data that already exists, so they are permanent:</p><table tabindex="0"><thead><tr><th>Name</th><th>Where</th></tr></thead><tbody><tr><td>key prefix <code>&#39;botwa&#39;</code></td><td>default <code>prefix</code> of <code>RedisStore</code>, <code>RedisCoordinator</code>, <code>RedisDurability</code>, <code>RedisScheduleStore</code> and <code>RedisLeaseProvider</code></td></tr><tr><td><code>$botwaMedia</code></td><td>media marker inside durable inbox records</td></tr><tr><td><code>&#39;botwa:durable&#39;</code>, <code>botwa.inbound.*</code>, <code>botwa.outbox</code></td><td>channel, event types and sidecar of <code>@botmesh/events/durability</code></td></tr><tr><td>database <code>botwa</code></td><td>default database of <code>MongoStore</code> and of the Postgres/MySQL connection strings</td></tr><tr><td><code>BOTWA_TEST_*</code></td><td>variables of the repository&#39;s own integration tests (never read by a published package)</td></tr></tbody></table><p>Pass your own <code>prefix</code>, <code>dbName</code> or connection string to use other names in a new deployment.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./stable-migration">Upgrade to stable: checklist and API changes</a></li><li><a href="./migration-2">Upgrade to stable: behaviour changes</a></li></ul>',36)])])}const b=t(s,[["render",i]]);export{m as __pageData,b as default};
